import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.writeEndArray().
 */
public class TokenBuffer_writeEndArray_TriageGen1Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteEndArray_Simple() throws IOException {
        // Test basic functionality: writeStartArray -> writeEndArray
        tokenBuffer.writeStartArray();
        tokenBuffer.writeEndArray();

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
    }

    @Test
    public void testWriteEndArray_NestedStructure() throws IOException {
        // Test context switching (moving up the hierarchy)
        // Start Object -> Start Array -> End Array -> End Object
        tokenBuffer.writeStartObject();
        tokenBuffer.writeStartArray();
        tokenBuffer.writeEndArray(); // Should move context back to Object level
        tokenBuffer.writeEndObject();

        JsonParser parser = tokenBuffer.asParser();

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        assertEquals(JsonToken.NOT_AVAILABLE, parser.nextToken());
    }

    @Test
    public void testWriteEndArray_DeeplyNested() throws IOException {
        // Test multiple levels of parent context traversal
        tokenBuffer.writeStartArray(); // Level 1
        tokenBuffer.writeStartArray(); // Level 2
        tokenBuffer.writeStartArray(); // Level 3

        tokenBuffer.writeEndArray(); // Returns to Level 2
        tokenBuffer.writeEndArray(); // Returns to Level 1
        tokenBuffer.writeEndArray(); // Returns to Root

        JsonParser parser = tokenBuffer.asParser();

        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.NOT_AVAILABLE, parser.nextToken());
    }

    @Test
    public void testWriteEndArray_WithUnbalancedRoot() throws IOException {
        // The method documentation says: "Let's allow unbalanced tho... i.e. not run out of root level, ever"
        // This tests the 'if (c != null)' branch when c is null (at the root level)
        tokenBuffer.writeEndArray();

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.NOT_AVAILABLE, parser.nextToken());
    }

    @Test
    public void testWriteEndArray_WithContent() throws IOException {
        // Test array with content to ensure token order is preserved
        tokenBuffer.writeStartArray();
        tokenBuffer.writeNumber(1);
        tokenBuffer.writeNumber(2);
        tokenBuffer.writeEndArray();

        JsonParser parser = tokenBuffer.asParser();
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(2, parser.getIntValue());
        assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        assertEquals(2, parser.getIntValue());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
    }
}
